<?php

namespace models\scolarite;

use core\Model;
use Database;
use models\acteurs\Etudiant;

/**
 * Modèle représentant un groupe d'étudiants rattaché à une promotion (table TD_GROUPE).
 *
 * @author  AutoGenerated / POO Refactor
 * @version 1.0
 */
class Groupe extends Model
{
    public string $GRP_ID;
    public string $PRO_ID;
    public string $GRP_LIBELLE;

    /**
     * Instancie et hydrate le modèle à partir d'un tableau associatif.
     *
     * @param array<string, mixed> $data
     * @return static
     */
    public static function fromArray(array $data): static
    {
        return (new static())->hydrate($data);
    }

    /**
     * Recherche un enregistrement par sa clé primaire (GRP_ID).
     *
     * @param string $id
     * @return static|null
     */
    public static function findById(string $id): ?static
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_GROUPE WHERE GRP_ID = ? LIMIT 1');
        $stmt->execute([$id]);
        $row = $stmt->fetch();

        return $row ? (new static())->hydrate($row) : null;
    }

    /**
     * Récupère tous les enregistrements de la table.
     *
     * @return static[]
     */
    public static function findAll(): array
    {
        $stmt = Database::getInstance()->query('SELECT * FROM TD_GROUPE');
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Récupère les instances Groupe associées à un objet Promo.
     *
     * @param Promo $source
     * @return static[]
     */
    public static function getFromPromo(Promo $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_GROUPE WHERE PRO_ID = ?');
        $stmt->execute([$source->PRO_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet Promo parent lié à cet enregistrement.
     *
     * @return Promo|null
     */
    public function getPromo(): ?Promo
    {
        if (!isset($this->PRO_ID)) {
            return null;
        }
        return Promo::findById($this->PRO_ID);
    }

    /**
     * Récupère la collection de Etudiant liée à cette instance.
     *
     * @return Etudiant[]
     */
    public function getEtudiants(): array
    {
        return Etudiant::getFromGroupe($this);
    }

}

if (!class_exists('models\Groupe', false)) {
